class Solution {
public:
 int countTrapezoids(vector<vector<int>>& points){
  using ll=long long;map<tuple<ll,ll,ll>,ll>lines;map<pair<ll,ll>,ll>slopes;map<pair<ll,ll>,map<pair<ll,ll>,ll>>mid;
  int n=points.size();for(int i=0;i<n;++i)for(int j=i+1;j<n;++j){ll dx=(ll)points[j][0]-points[i][0],dy=(ll)points[j][1]-points[i][1];ll a=llabs(dx),b=llabs(dy);while(b){ll t=a%b;a=b;b=t;}ll g=a;dx/=g;dy/=g;if(dx<0||(dx==0&&dy<0)){dx=-dx;dy=-dy;}
   ll c=dy*points[i][0]-dx*points[i][1];++lines[{dx,dy,c}];++slopes[{dx,dy}];++mid[{(ll)points[i][0]+points[j][0],(ll)points[i][1]+points[j][1]}][{dx,dy}];}
  ll ans=0;for(auto &p:slopes)ans+=p.second*(p.second-1)/2;
  for(auto&p:lines)ans-=p.second*(p.second-1)/2;
  for(auto&p:mid){ll sum=0,all=0;for(auto&t:p.second){all+=t.second;sum+=t.second*(t.second-1)/2;}ans-=all*(all-1)/2-sum;}
  return (int)ans;
 }
};
